29	/**
30	 * Simple JavaBean domain object representing an owner.
31	 *
32	 * @author Ken Krebs
33	 * @author Juergen Hoeller
34	 * @author Sam Brannen
35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "postcode")
49	    private String postcode;
50	
51	    @Column(name = "telephone")
52	    @NotEmpty
53	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
54	    private String telephone;
55	
56	    @Column(name = "email")
57	    @Email
58	    private String email;
59	
60	    @Column(name = "registration_date")
61	    private LocalDate registrationDate;
62	
63	    @Column(name = "birth_date")
64	    private LocalDate birthDate;
65	
66	    @Column(name = "customer_code")
67	    private String customerCode;
68	
69	    @Column(name = "household_id")
70	    private String householdId;
71	
72	    @Column(name = "namesake_count")
73	    private Integer namesakeCount;
74	
75	    @Column(name = "bulk_signup_warning")
76	    private Boolean bulkSignupWarning;
77	
78	    @Column(name = "household_size")
79	    private Integer householdSize;
80	
81	    @Column(name = "possible_duplicate")
82	    private Boolean possibleDuplicate;
83	
84	    @Column(name = "possible_duplicate_of")
85	    private Integer possibleDuplicateOf;
86	
87	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
88	    private Set<Pet> pets;
89	
90	    public String getAddress() {
91	        return this.address;
92	    }
93	
94	    public void setAddress(String address) {
95	        this.address = address;
96	    }
97	
98	    public String getCity() {
99	        return this.city;
100	    }
101	
102	    public void setCity(String city) {
103	        this.city = city;
104	    }
105	
106	    public String getPostcode() {
107	        return this.postcode;
108	    }
109	
110	    public void setPostcode(String postcode) {
111	        this.postcode = postcode;
112	    }
113	
114	    public String getTelephone() {
115	        return this.telephone;
116	    }
117	
118	    public void setTelephone(String telephone) {
119	        this.telephone = telephone;
120	    }
121	
122	    public String getEmail() {
123	        return this.email;
124	    }
125	
126	    public void setEmail(String email) {
127	        this.email = email == null ? null : email.toLowerCase();
128	    }
129	
130	    public LocalDate getRegistrationDate() {
131	        return this.registrationDate;
132	    }
133	
134	    public void setRegistrationDate(LocalDate registrationDate) {
135	        this.registrationDate = registrationDate;
136	    }
137	
138	    public LocalDate getBirthDate() {
139	        return this.birthDate;
140	    }
141	
142	    public void setBirthDate(LocalDate birthDate) {
143	        this.birthDate = birthDate;
144	    }
145	
146	    /**
147	     * The owner's age band derived from {@link #birthDate} relative to the
148	     * {@link #registrationDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} from 18 to 64,
149	     * and {@code 'SENIOR'} at 65 or older. Returns {@code null} when no birthDate is set. The age
150	     * is the number of complete years between the birthDate and the registrationDate (or the
151	     * current date when the registrationDate is not yet set).
152	     */
153	    public String getAgeBand() {
154	        if (this.birthDate == null) {
155	            return null;
156	        }
157	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
158	        int years = Period.between(this.birthDate, reference).getYears();
159	        if (years < 18) {
160	            return "MINOR";
161	        }
162	        if (years < 65) {
163	            return "ADULT";
164	        }
165	        return "SENIOR";
166	    }
167	
168	    public String getCustomerCode() {
169	        return this.customerCode;
170	    }
171	
172	    public void setCustomerCode(String customerCode) {
173	        this.customerCode = customerCode;
174	    }
175	
176	    public String getHouseholdId() {
177	        return this.householdId;
178	    }
179	
180	    public void setHouseholdId(String householdId) {
181	        this.householdId = householdId;
182	    }
183	
184	    public Integer getNamesakeCount() {
185	        return this.namesakeCount;
186	    }
187	
188	    public void setNamesakeCount(Integer namesakeCount) {
189	        this.namesakeCount = namesakeCount;
190	    }
191	
192	    public Boolean getBulkSignupWarning() {
193	        return this.bulkSignupWarning;
194	    }
195	
196	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
197	        this.bulkSignupWarning = bulkSignupWarning;
198	    }
199	
200	    public Integer getHouseholdSize() {
201	        return this.householdSize;
202	    }
203	
204	    public void setHouseholdSize(Integer householdSize) {
205	        this.householdSize = householdSize;
206	    }
207	
208	    public Boolean getPossibleDuplicate() {
209	        return this.possibleDuplicate;
210	    }
211	
212	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
213	        this.possibleDuplicate = possibleDuplicate;
214	    }
215	
216	    public Integer getPossibleDuplicateOf() {
217	        return this.possibleDuplicateOf;
218	    }
219	
220	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
221	        this.possibleDuplicateOf = possibleDuplicateOf;
222	    }
223	
224	    /**
225	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
226	     */
227	    public String getDisplayName() {
228	        return this.getLastName() + ", " + this.getFirstName();
229	    }
230	
231	    /**
232	     * The owner's initials: the upper-cased first letters of firstName and lastName,
233	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
234	     */
235	    public String getInitials() {
236	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
237	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
238	    }
239	
240	    /**
241	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
242	     * last two digits of the registrationDate year, e.g. {@code 'NSW-3C1A9F2B-M26'}.
243	     */
244	    public String getMembershipNumber() {
245	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
246	    }
247	
248	    /**
249	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) computed over the decimal digits
250	     * contained in the owner's {@link #customerCode}.
251	     */
252	    public int getCheckDigit() {
253	        return luhnCheckDigit(this.customerCode);
254	    }
255	
256	    /**
257	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
258	     * contained in {@code value}. Reading the digits right to left, every second one is
259	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
260	     * digits are summed, and the check digit is the amount that must be added to that sum to
261	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
262	     * the digit is taken over exactly the digits the string carries.
263	     */
264	    private static int luhnCheckDigit(String value) {
265	        int sum = 0;
266	        boolean doubling = true;
267	        for (int i = value.length() - 1; i >= 0; i--) {
268	            char c = value.charAt(i);
269	            if (c < '0' || c > '9') {
270	                continue;
271	            }
272	            int digit = c - '0';
273	            if (doubling) {
274	                digit *= 2;
275	                if (digit > 9) {
276	                    digit -= 9;
277	                }
278	            }
279	            sum += digit;
280	            doubling = !doubling;
281	        }
282	        return (10 - (sum % 10)) % 10;
283	    }
284	
285	    /** Fixed city-to-region table used to derive an owner's locality. */
286	    private static final Map<String, String> CITY_REGION = Map.of(
287	        "Sydney", "NSW",
288	        "Melbourne", "VIC",
289	        "Brisbane", "QLD");
290	
291	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
292	    public static final String UNKNOWN_REGION = "UNKNOWN";
293	
294	    /**
295	     * The canonical region for a city, derived from the fixed city-to-region table
296	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
297	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
298	     * source of the city-to-region mapping, shared by every rule that is keyed by
299	     * region so the mapping is never re-derived elsewhere.
300	     */
301	    public static String regionOf(String city) {
302	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
303	    }
304	
305	    /**
306	     * The owner's locality: the {@code <REGION>} component of the {@link #getCustomerCode()
307	     * customerCode} (its prefix up to the first {@code '-'}), which is the region derived from
308	     * the owner's postcode at creation ({@link #UNKNOWN_REGION} when the postcode maps to no
309	     * known region). Locality is read from the region-and-hash identity so it never re-derives
310	     * a region of its own; it is {@link #UNKNOWN_REGION} for an owner that has no customerCode.
311	     */
312	    public String getLocality() {
313	        if (this.customerCode == null) {
314	            return UNKNOWN_REGION;
315	        }
316	        int dash = this.customerCode.indexOf('-');
317	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
318	    }
319	
320	    /**
321	     * The region derived from this owner's postcode alone: the region whose fixed
322	     * {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the postcode, or {@code null}
323	     * when the postcode is absent, not four digits, or in no known range. This is the {@code <REGION>}
324	     * component built into the owner's customer code at creation and, through it, the source of the
325	     * owner's {@linkplain #getLocality() locality}. It is the single place a region is read from an
326	     * owner's postcode, so every rule keyed by the postcode-derived region shares one derivation.
327	     */
328	    public String getRegion() {
329	        return regionOfPostcode(this.postcode);
330	    }
331	
332	    /**
333	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
334	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
335	     * no known range.
336	     */
337	    private static String regionOfPostcode(String postcode) {
338	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
339	            return null;
340	        }
341	        int value = Integer.parseInt(postcode);
342	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
343	            int[] range = entry.getValue();
344	            if (value >= range[0] && value <= range[1]) {
345	                return entry.getKey();
346	            }
347	        }
348	        return null;
349	    }
350	
351	    /**
352	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
353	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
354	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
355	     */
356	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
357	        "NSW", new int[] {2000, 2099},
358	        "VIC", new int[] {3000, 3099},
359	        "QLD", new int[] {4000, 4099});
360	
361	    /**
362	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
363	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
364	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
365	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
366	     * city with no known region accepts any 4-digit postcode.
367	     */
368	    public boolean isPostcodeValid() {
369	        if (this.postcode == null) {
370	            return true;
371	        }
372	        if (!this.postcode.matches("[0-9]{4}")) {
373	            return false;
374	        }
375	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
376	        if (range == null) {
377	            return true;
378	        }
379	        int value = Integer.parseInt(this.postcode);
380	        return value >= range[0] && value <= range[1];
381	    }
382	
383	    /**
384	     * The national (subscriber) digit count required by each known country calling code, keyed by
385	     * the code's digits (without the leading {@code '+'}): {@code '+1'} carries 10 national digits
386	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
387	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
388	     * re-derived elsewhere.
389	     */
390	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
391	        "1", 10,
392	        "61", 9);
393	
394	    /**
395	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
396	     * E.164 digit string, choosing the longest matching code known to
397	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
398	     * country code. This is the single place a country code is read from an E.164 number, so every
399	     * rule keyed by that code shares one derivation.
400	     */
401	    private static String countryCodeOf(String e164Digits) {
402	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
403	            .filter(e164Digits::startsWith)
404	            .max(Comparator.comparingInt(String::length))
405	            .orElse(null);
406	    }
407	
408	    /**
409	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
410	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
411	     * known code wins; a number whose country code is not recognised passes this check (its length is
412	     * then governed only by the general E.164 bound), while a recognised code must be followed by
413	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
414	     */
415	    public static boolean hasValidNationalLength(String e164Digits) {
416	        String countryCode = countryCodeOf(e164Digits);
417	        if (countryCode == null) {
418	            return true;
419	        }
420	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
421	    }
422	
423	    /**
424	     * The owner's membership level, a number from 1 to 3 determined on creation: it starts at 1,
425	     * gains 1 when an email is present, gains 1 when namesakeCount is 0, and is capped at 3.
426	     * Level 4 is reserved for tenure.
427	     */
428	    public Integer getMembershipLevel() {
429	        int level = 1;
430	        if (this.email != null && !this.email.isEmpty()) {
431	            level++;
432	        }
433	        if (this.namesakeCount != null && this.namesakeCount == 0) {
434	            level++;
435	        }
436	        return Math.min(level, 3);
437	    }
438	
439	    /**
440	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
441	     * otherwise {@code 'PHONE'}.
442	     */
443	    public String getContactPreference() {
444	        return (this.email != null && !this.email.isEmpty()) ? "EMAIL" : "PHONE";
445	    }
446	
447	    /**
448	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
449	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
450	     * the national digits grouped into threes from the left separated by spaces,
451	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
452	     * telephone} stays in E.164. Returns the telephone unchanged when it is {@code null}, not in
453	     * E.164 form, or carries no known country code.
454	     */
455	    public String getTelephoneDisplay() {
456	        if (this.telephone == null || !this.telephone.startsWith("+")) {
457	            return this.telephone;
458	        }
459	        String digits = this.telephone.substring(1);
460	        String countryCode = countryCodeOf(digits);
461	        if (countryCode == null) {
462	            return this.telephone;
463	        }
464	        String national = digits.substring(countryCode.length());
465	        StringBuilder groups = new StringBuilder();
466	        for (int i = 0; i < national.length(); i += 3) {
467	            if (groups.length() > 0) {
468	                groups.append(' ');
469	            }
470	            groups.append(national, i, Math.min(i + 3, national.length()));
471	        }
472	        return "+" + countryCode + " " + groups;
473	    }
474	
475	    /**
476	     * The owner's identity key: the single derived value used for duplicate detection.
477	     * It joins the normalized (E.164) telephone, the email (already lower-cased, or the
478	     * empty string when absent) and the householdId (or the empty string when the owner
479	     * has no household) with {@code '|'}, e.g. {@code '+61412345678|jane@example.test|3C1A9F2B7D4E'}.
480	     * Two owners are duplicates only when their whole identity keys are equal.
481	     */
482	    public String getIdentityKey() {
483	        String telephonePart = this.telephone == null ? "" : this.telephone;
484	        String emailPart = this.email == null ? "" : this.email;
485	        String householdPart = this.householdId == null ? "" : this.householdId;
486	        return telephonePart + "|" + emailPart + "|" + householdPart;
487	    }
488	
489	    protected Set<Pet> getPetsInternal() {
490	        if (this.pets == null) {
491	            this.pets = new HashSet<>();
492	        }
493	        return this.pets;
494	    }
495	
496	    protected void setPetsInternal(Set<Pet> pets) {
497	        this.pets = pets;
498	    }
499	
500	    public List<Pet> getPets() {
501	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
502	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
503	        return Collections.unmodifiableList(sortedPets);
504	    }
505	
506	    public void setPets(List<Pet> pets) {
507	        this.pets = new HashSet<>(pets);
508	    }
509	
510	    public void addPet(Pet pet) {
511	        getPetsInternal().add(pet);
512	        pet.setOwner(this);
513	    }
514	
515	    /**
516	     * Return the Pet with the given name, or null if none found for this Owner.
517	     *
518	     * @param name to test
519	     * @return true if pet name is already in use
520	     */
521	    public Pet getPet(String name) {
522	        return getPet(name, false);
523	    }
524	
525	    /**
526	     * Return the Pet with the given name, or null if none found for this Owner.
527	     *
528	     * @param name to test
529	     * @return true if pet name is already in use
530	     */
531	    public Pet getPet(String name, boolean ignoreNew) {
532	        name = name.toLowerCase();
533	        for (Pet pet : getPetsInternal()) {
534	            if (!ignoreNew || !pet.isNew()) {
535	                String compName = pet.getName();
536	                compName = compName.toLowerCase();
537	                if (compName.equals(name)) {
538	                    return pet;
539	                }
540	            }
541	        }
542	        return null;
543	    }
544	
545	    public Pet getPet(Integer petId) {
546	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
547	    }
548	
549	    @Override
550	    public String toString() {
551	        return new ToStringCreator(this)
552	
553	            .append("id", this.getId())
554	            .append("new", this.isNew())
555	            .append("lastName", this.getLastName())
556	            .append("firstName", this.getFirstName())
557	            .append("address", this.address)
558	            .append("city", this.city)
559	            .append("telephone", this.telephone)
560	            .append("email", this.email)
561	            .toString();
562	    }
563	}
