114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
117	
118	        HttpStatus invalid = normalizeAndValidate(owner);
119	        if (invalid != null) {
120	            return new ResponseEntity<>(invalid);
121	        }
122	        if (isDailyLimitReached(owner.getRegistrationDate())) {
123	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
124	        }
125	
126	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
127	        assignHousehold(owner);
128	
129	        HttpStatus conflict = checkForConflicts(owner, sharesHousehold);
130	        if (conflict != null) {
131	            return new ResponseEntity<>(conflict);
132	        }
133	
134	        assignDerivedAttributes(owner, sharesHousehold);
135	        this.clinicService.saveOwner(owner);
136	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
137	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
