141	    /**
142	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
143	     * rejected. The owner's address is normalized (a blank address is rejected), its telephone is
144	     * converted to E.164 (an unconvertible number is rejected), its postcode is checked against its
145	     * city's region, a registration date in the future is rejected, and the effective registration
146	     * date (the supplied one, or today when none was given) is rolled onto a business day and stored
147	     * back on the owner. Returns {@code null} once the owner is valid and normalized, or the
148	     * {@link HttpStatus} the create must fail with ({@code 400 Bad Request}) otherwise.
149	     */
150	    private HttpStatus normalizeAndValidate(Owner owner) {
151	        String address = addressNormalizer.normalize(owner.getAddress());
152	        if (address.isEmpty()) {
153	            return HttpStatus.BAD_REQUEST;
154	        }
155	        owner.setAddress(address);
156	        String telephone = toE164(owner.getTelephone());
157	        if (telephone == null) {
158	            return HttpStatus.BAD_REQUEST;
159	        }
160	        owner.setTelephone(telephone);
161	        if (!owner.isPostcodeValid()) {
162	            return HttpStatus.BAD_REQUEST;
163	        }
164	        if (owner.getRegistrationDate() != null
165	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
166	            return HttpStatus.BAD_REQUEST;
167	        }
168	        LocalDate effectiveDate = owner.getRegistrationDate() != null
169	            ? owner.getRegistrationDate() : LocalDate.now();
170	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
171	        return null;
172	    }
173	
174	    /**
175	     * Assign the owner its household link. The {@link #householdId(Owner) householdId} is computed
176	     * deterministically from the owner's lastName and postcode, so every owner sharing that
177	     * lastName and postcode is assigned the same value automatically, independent of whether the
178	     * owner declares it shares a household. The link is assigned before the
179	     * {@link #checkForConflicts(Owner, boolean) conflict checks} because it is part of the owner's
180	     * {@link Owner#getIdentityKey() identity} and feeds its {@link #householdSize(String) household
181	     * size}.
182	     */
183	    private void assignHousehold(Owner owner) {
184	        owner.setHouseholdId(householdId(owner));
185	    }
186	
187	    /**
188	     * Whether the owner clashes with an owner that already exists, and the {@link HttpStatus} the
189	     * create must fail with when it does. An owner is rejected with {@code 409 Conflict} when it
190	     * {@link #isHouseholdDuplicate(Owner) duplicates an existing household} or when its
191	     * {@link #isCityAtCapacity(String) city is already at capacity}. Declaring {@code
192	     * sharesHousehold} bypasses only the household-duplicate block (the owner is then created as a
193	     * declared household member); it does not lift the city-capacity limit. Returns {@code null}
194	     * when the owner clashes with nothing and may be created.
195	     */
196	    private HttpStatus checkForConflicts(Owner owner, boolean sharesHousehold) {
197	        if (!sharesHousehold && isHouseholdDuplicate(owner)) {
198	            return HttpStatus.CONFLICT;
199	        }
200	        if (isCityAtCapacity(owner.getCity())) {
201	            return HttpStatus.CONFLICT;
202	        }
203	        return null;
204	    }
