206	    /**
207	     * Build the {@code 201 Created} response for a persisted owner: its {@link OwnerDto} body and a
208	     * {@code Location} header pointing at {@code /api/owners/{id}}.
209	     */
210	    private ResponseEntity<OwnerDto> created(Owner owner) {
211	        HttpHeaders headers = new HttpHeaders();
212	        headers.setLocation(UriComponentsBuilder.newInstance()
213	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
214	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), headers, HttpStatus.CREATED);
215	    }
216	
217	    /**
218	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
219	     * {@link #customerCode(Owner) customerCode}, {@link #namesakeCount(String, String) namesakeCount},
220	     * {@link #isBulkSignup(LocalDate) bulk-signup warning} and {@link #householdSize(String)
221	     * householdSize}. Each is computed from the owner's own fields together with the owners already
222	     * present, so this runs after the owner has been validated and has passed the duplicate and
223	     * capacity checks, and immediately before it is persisted.
224	     */
225	    private void assignDerivedAttributes(Owner owner, boolean sharesHousehold) {
226	        owner.setCustomerCode(customerCode(owner));
227	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
228	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
229	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
230	        assignPossibleDuplicate(owner, sharesHousehold);
231	    }
232	
233	    /**
234	     * Flag a newly created owner as a possible (soft) duplicate. An owner that declares it shares a
235	     * household ({@code sharesHousehold}) is a declared household member, not a suspected duplicate,
236	     * so it is never flagged. Otherwise, because this runs after the hard
237	     * {@link #isHouseholdDuplicate(Owner) household-duplicate} check, the owner is not a household
238	     * match; it is flagged only when it is a soft match of an existing owner as determined by
239	     * {@link #findSoftDuplicate(Owner)}. When such an owner exists the new owner is flagged with
240	     * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to that owner's id;
241	     * otherwise {@code possibleDuplicate = false} and no matching id is recorded.
242	     */
243	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
244	        Owner match = sharesHousehold ? null : findSoftDuplicate(owner);
245	        owner.setPossibleDuplicate(match != null);
246	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
247	    }
248	
249	    /**
250	     * The existing owner this owner softly duplicates, or {@code null} when there is none. A soft
251	     * match is an existing owner that shares this owner's lastName (compared case-insensitively,
252	     * with collapsed whitespace) and its postcode but carries a different telephone; the earliest
253	     * such owner (by id) is returned. A postcode is required for a soft match, so an owner without a
254	     * postcode never matches.
255	     */
256	    private Owner findSoftDuplicate(Owner owner) {
257	        if (owner.getPostcode() == null) {
258	            return null;
259	        }
260	        String candidateLastName = normalizeName(owner.getLastName());
261	        return this.clinicService.findAllOwners().stream()
262	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
263	            .filter(existing -> normalizeName(existing.getLastName()).equals(candidateLastName))
264	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
265	            .min(Comparator.comparingInt(Owner::getId))
266	            .orElse(null);
267	    }
268	
269	    /**
270	     * Build the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
271	     * where REGION is the region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION}
272	     * when the postcode is absent or maps to no known region) and HASH8 is the first 8 upper-case
273	     * hex characters of the SHA-256 of the normalized (E.164) telephone concatenated with the
274	     * lastName (e.g. {@code 'NSW-3C1A9F2B'}). This is the single source of the owner's identity:
275	     * every value built from the customer code (the membership number and its check digit) and the
276	     * owner's locality are derived from it.
277	     */
278	    private String customerCode(Owner owner) {
279	        String region = owner.getRegion() != null ? owner.getRegion() : Owner.UNKNOWN_REGION;
280	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName()).substring(0, 8);
281	        return region + "-" + hash8;
282	    }
283	
284	    /**
285	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
286	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
287	     * (business-day) registration date of the owner being created, so owners are counted per
288	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
289	     */
290	    private boolean isDailyLimitReached(LocalDate day) {
291	        long count = this.clinicService.findAllOwners().stream()
292	            .filter(existing -> day.equals(existing.getRegistrationDate()))
293	            .count();
294	        return count >= 100;
295	    }
296	
297	    /**
298	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
299	     * more than 80 owners have already been created for the given business day. Counts the owners
300	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
301	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
302	     * warning.
303	     */
304	    private boolean isBulkSignup(LocalDate day) {
305	        long count = this.clinicService.findAllOwners().stream()
306	            .filter(existing -> day.equals(existing.getRegistrationDate()))
307	            .count();
308	        return count > 80;
309	    }
310	
311	    /**
312	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
313	     * advance it to the following Monday; a weekday is returned unchanged.
314	     */
315	    private LocalDate toBusinessDay(LocalDate date) {
316	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
317	            date = date.plusDays(1);
318	        }
319	        return date;
320	    }
321	
322	    /**
323	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
324	     * more owners. Cities are compared case-insensitively.
325	     */
326	    private boolean isCityAtCapacity(String city) {
327	        long count = this.clinicService.findAllOwners().stream()
328	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
329	            .count();
330	        return count >= 50;
331	    }
332	
333	    /**
334	     * The number of existing owners that already share the given firstName and lastName,
335	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
336	     * whitespace runs collapsed). Counted over the owners present before this create.
337	     */
338	    private int namesakeCount(String firstName, String lastName) {
339	        String candidateFirstName = normalizeName(firstName);
340	        String candidateLastName = normalizeName(lastName);
341	        return (int) this.clinicService.findAllOwners().stream()
342	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
343	                && normalizeName(existing.getLastName()).equals(candidateLastName))
344	            .count();
345	    }
346	
347	    /**
348	     * The number of members in this owner's household after this create: the count of existing
349	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
350	     * created. An owner with no household ({@code householdId == null}) is a household of one.
351	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
352	     * does not depend on the order in which household members were created.
353	     */
354	    private int householdSize(String householdId) {
355	        if (householdId == null) {
356	            return 1;
357	        }
358	        long existing = this.clinicService.findAllOwners().stream()
359	            .filter(other -> householdId.equals(other.getHouseholdId()))
360	            .count();
361	        return (int) existing + 1;
362	    }
363	
364	    /**
365	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
366	     * cannot form a valid E.164 number.
367	     *
368	     * <p>A leading '+' and country code are kept when present; otherwise country code
369	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
370	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
371	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
372	     * exactly the national-digit count that code requires (see
373	     * {@link Owner#hasValidNationalLength}); otherwise it is rejected as invalid.
374	     */
375	    private String toE164(String telephone) {
376	        if (telephone == null) {
377	            return null;
378	        }
379	        boolean hasCountryCode = telephone.trim().startsWith("+");
380	        String digits = telephone.replaceAll("\\D", "");
381	        String e164;
382	        if (hasCountryCode) {
383	            e164 = digits;
384	        } else {
385	            if (digits.startsWith("0")) {
386	                digits = digits.substring(1);
387	            }
388	            e164 = "61" + digits;
389	        }
390	        if (e164.length() < 8 || e164.length() > 15) {
391	            return null;
392	        }
393	        if (!Owner.hasValidNationalLength(e164)) {
394	            return null;
395	        }
396	        return "+" + e164;
397	    }
398	
399	    /**
400	     * Whether the candidate owner belongs to a household that already exists, and so must be
401	     * rejected with {@code 409 Conflict} unless it declares {@code sharesHousehold}. The household
402	     * is keyed by the deterministic {@link #householdId(Owner) householdId} (derived from lastName
403	     * and postcode), so any existing owner carrying the same householdId means this owner is a
404	     * second member of an already-registered household. Two owners sharing a lastName and postcode
405	     * are therefore the same household: the second is a household duplicate.
406	     */
407	    private boolean isHouseholdDuplicate(Owner owner) {
408	        String householdId = owner.getHouseholdId();
409	        if (householdId == null) {
410	            return false;
411	        }
412	        return this.clinicService.findAllOwners().stream()
413	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
414	    }
415	
416	    /**
417	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
418	     * to a single space and lower-case. A null value normalizes to the empty string.
419	     */
420	    private String normalizeName(String value) {
421	        if (value == null) {
422	            return "";
423	        }
424	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
425	    }
426	
427	    /**
428	     * A stable shared identifier for the household an owner belongs to, derived deterministically
429	     * from its lastName and postcode. The lastName is normalized (case-insensitive,
430	     * whitespace-collapsed) before hashing, so every owner sharing the same lastName and postcode is
431	     * assigned the same value regardless of the order in which they are created. Formatted as the
432	     * first 12 upper-case hex characters of the SHA-256 of {@code '<normalizedLastName>|<postcode>'}
433	     * (an absent postcode contributes the empty string).
434	     */
435	    private String householdId(Owner owner) {
436	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
437	        String key = normalizeName(owner.getLastName()) + "|" + postcode;
438	        return shaHexUpper(key).substring(0, 12);
439	    }
440	
441	    /**
442	     * The SHA-256 digest of {@code input}'s UTF-8 bytes, rendered as an upper-case hexadecimal
443	     * string (two hex characters per digest byte, so 64 characters in all). This is the single
444	     * place the hashing-and-hex-encoding is performed; callers that need a shorter opaque token
445	     * take a prefix of the result (e.g. {@link #householdId} keeps the first 12 characters and
446	     * {@link #customerCode} keeps the first 8).
447	     */
448	    private String shaHexUpper(String input) {
449	        try {
450	            byte[] digest = MessageDigest.getInstance("SHA-256")
451	                .digest(input.getBytes(StandardCharsets.UTF_8));
452	            StringBuilder sb = new StringBuilder(digest.length * 2);
453	            for (byte b : digest) {
454	                sb.append(String.format("%02x", b));
455	            }
456	            return sb.toString().toUpperCase();
457	        }
458	        catch (NoSuchAlgorithmException e) {
459	            throw new IllegalStateException("SHA-256 not available", e);
460	        }
461	    }
